from pathlib import Path
import json,hashlib
OUT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text())
def save(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2))
s=read(OUT/'results/r4_development/summary.json');means={n:next(g['mean'] for g in x['groups'] if g['mode']==3 and g['group']=='ALL') for n,x in s.items()};assert min(means,key=means.get)=='route';rows={n:read(OUT/f'results/r4_development/{n}_rows.json') for n in s};fields=['cleared_count','source_count','complete','exit_reason','error','average_clear_time_s','total_virtual_time_s','distance_m','requests','clear_failures'];idx={r['case_id']:r for r in rows['parent']};assert all(r['complete'] for z in rows.values() for r in z);assert all(r[k]==idx[r['case_id']][k] for z in rows.values() for r in z if r['mode']==4 for k in fields)
src=(OUT/'snapshots/r4_development.py').read_text().replace('lens_clear="parent"),','lens_clear="route"),');(OUT/'snapshots/r4_solver.py').write_text(src)
result=dict(selected='route',development_means=means,q4_exact=True,candidate_sha256=hashlib.sha256(src.encode()).hexdigest(),geometry_checks=sum(v['geometry_checks'] for v in s.values()),synthetic_geometry=read(OUT/'results/r4_geometry.json')|{'rows':None},diagnostics={n:dict(lens_calls=sum(r['counters'].get('lens_calls',0) for r in z),fixed_state_proxy_saved_m=sum(r['counters'].get('lens_proxy_saved_m',0.) for r in z)) for n,z in rows.items()},boundary='Development selection; nearest-entry-only negative; no new final.')
save(OUT/'research/r4_selection.json',result);p=read(OUT/'optimization_path.json');p['rounds'][-1].update(status='frozen_awaiting_regression',after_development=result);save(OUT/'optimization_path.json',p)
(OUT/'research/r4_reliability.md').write_text('''# R4 全合法清除位置与路线代理\n\n设真实源s在凸多边形P内。一个点q能认证clear当且仅当P的所有顶点到q距离≤20米；充分性由范数凸性，必要性由顶点属于P。因此合法动作域K是所有顶点为圆心、半径20米圆盘的交集。旧B(c,20-r)为K子集，A2最近投影在K上优化进入距离，本轮新增进入+后继距离。\n\nK边界由这些圆的可行圆弧组成。半径取20−1e−7以保留严格数值余量。对中心v的边界点q=v+r*u，另一中心w约束等价u·(w−v)≥距离(v,w)^2/(2r)，得到角度区间交集；每个非空区间保留端点、16格采样后对局部低点作28次黄金细化。直线段start→successor与所有圆盘相交时，其共同参数区间给出等于直接距离的最短代理。其余弧搜索只宣称有限候选近似，不宣称全局最优。\n\n每个新候选都全顶点复核；旧落点始终保留，因此固定状态进入+后继预测费用不高于父法。多于32顶点时放弃额外优化保留父点，这不会删除任何合法动作或破坏证书。最终断言max_v距离(q,v)≤20+1e−8；真实反馈若违反认证仍按父法报告异常。预测后继可能改变，不能据固定状态代理推出整个在线任务不差，必须实跑所有案例。\n\n不新增measure/clear动作，不删搜索站，不改真实定位集合与共享预算。新位置离真实源≤20米，因此位置宽松3500米界仍成立，R3统一283091秒虚拟界继续成立。真实测向在新位置产生的后续差异由正常接口处理。1000合成区域和5000凸组合包含检查全过，只是有限实现辅助证据；连续保证来自凸性与顶点复核。HTTP/并发/重试不变。\n\n开发父233.389232130、A2最近进入233.420954829、全区域路线233.230353013秒/源，三者384例均全清，Q4逐行相同。全区域最近点会改变后继路线，确实可能小幅整体退步；不把两个旧父收益相加。\n''')
print({k:v for k,v in result.items() if k!='synthetic_geometry'})
